const phraseAt = (text, fraction) => {
  const words = text.split(/\s+/);
  const index = Math.min(words.length - 4, Math.max(0, Math.floor(words.length * fraction)));
  return words.slice(index, index + 4).join(" ").replace(/[.,;:!?]+$/, "");
};

